def prune_isolated_refs(worktree: pathlib.Path) -> None:
    head_proc = run_cmd(["git", "symbolic-ref", "-q", "HEAD"], cwd=worktree)
    current = head_proc.stdout.strip() if head_proc.returncode == 0 else ""
    proc = run_cmd(["git", "for-each-ref", "--format=%(refname)"], cwd=worktree)
    for ref in proc.stdout.splitlines():
        ref = ref.strip()
        if ref and ref != current:
            run_cmd(["git", "update-ref", "-d", ref], cwd=worktree)


def ignore_benchmark_plugin(worktree: pathlib.Path) -> None:
    proc = run_cmd(["git", "rev-parse", "--git-path", "info/exclude"], cwd=worktree, check=True)
